-- No demo data or accounts. Every operation uses an authenticated actor.
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;
create table public.academies (
 id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 2 and 120),
 country text not null, currency text not null check(currency ~ '^[A-Z]{3}$'), timezone text not null,
 primary_color text not null default '#215c50' check(primary_color ~ '^#[0-9a-fA-F]{6}$'),
 logo_path text, contact text, receipt_footer text, grace_days int not null default 5 check(grace_days between 0 and 90),
 billing_day int check(billing_day between 1 and 31), allow_negative_stock boolean not null default false,
 expense_approval_limit numeric(14,2) not null default 0 check(expense_approval_limit>=0),
 collection_template text not null default 'Hola {nombre}, tu saldo pendiente es {saldo}. Comunícate con recepción para acordar tu pago.',
 receipt_prefix text not null default 'REC', created_at timestamptz not null default now()
);
create table public.branches (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), name text not null, address text, phone text, active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.roles (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), name text not null, permissions text[] not null, active boolean not null default true, unique(academy_id,name), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.internal_members (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), user_id uuid not null references auth.users(id), name text not null, active boolean not null default true, all_branches boolean not null default false, branch_ids uuid[] not null default '{}', unique(academy_id,user_id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.member_roles (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), member_id uuid not null, foreign key(academy_id,member_id) references public.internal_members(academy_id,id), role_id uuid not null, foreign key(academy_id,role_id) references public.roles(academy_id,id), unique(member_id,role_id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.rooms (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), name text not null, capacity int not null check(capacity>0), active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.disciplines (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), name text not null, active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.belts (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), discipline_id uuid not null, foreign key(academy_id,discipline_id) references public.disciplines(academy_id,id), name text not null, rank int not null default 0, active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.student_groups (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), name text not null, min_age int, max_age int, active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.contacts (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), name text not null, email text, phone text, address text, linked_user_id uuid references auth.users(id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.students (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), name text not null check(length(name)>1), email text, phone text, birth_date date, joined_on date not null default current_date, status text not null default 'activo' check(status in ('activo','pausado','retirado')), status_reason text, emergency_name text, emergency_phone text, photo_path text, payer_id uuid , foreign key(academy_id,payer_id) references public.contacts(academy_id,id), group_id uuid , foreign key(academy_id,group_id) references public.student_groups(academy_id,id), discipline_id uuid , foreign key(academy_id,discipline_id) references public.disciplines(academy_id,id), linked_user_id uuid references auth.users(id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.student_guardians (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), student_id uuid not null, foreign key(academy_id,student_id) references public.students(academy_id,id), contact_id uuid not null, foreign key(academy_id,contact_id) references public.contacts(academy_id,id), relationship text not null, is_payer boolean not null default false, unique(student_id,contact_id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.student_progress (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), student_id uuid not null, foreign key(academy_id,student_id) references public.students(academy_id,id), belt_id uuid not null, foreign key(academy_id,belt_id) references public.belts(academy_id,id), degree int not null default 0 check(degree>=0), promoted_on date not null, notes text, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.student_notes (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), student_id uuid not null, foreign key(academy_id,student_id) references public.students(academy_id,id), body text not null, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.documents (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), student_id uuid , foreign key(academy_id,student_id) references public.students(academy_id,id), title text not null, path text not null unique, mime_type text not null check(mime_type in ('application/pdf','image/jpeg','image/png')), size_bytes int not null check(size_bytes between 1 and 5242880), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.prospects (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), name text not null, email text, phone text, status text not null default 'nuevo' check(status in ('nuevo','prueba','convertido','descartado')), trial_at timestamptz, notes text, student_id uuid , foreign key(academy_id,student_id) references public.students(academy_id,id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.plans (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), name text not null, kind text not null check(kind in ('ilimitado','semanal','paquete','visita','privada','familiar','servicio')), discipline_id uuid , foreign key(academy_id,discipline_id) references public.disciplines(academy_id,id), branch_id uuid , foreign key(academy_id,branch_id) references public.branches(academy_id,id), active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.plan_versions (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), plan_id uuid not null, foreign key(academy_id,plan_id) references public.plans(academy_id,id), price numeric(14,2) not null check(price>=0), months int not null default 1 check(months between 1 and 12), valid_days int not null default 30 check(valid_days>0), weekly_limit int check(weekly_limit>0), class_count int check(class_count>0), effective_on date not null, renewable boolean not null default true, unique(plan_id,effective_on), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.memberships (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), student_id uuid not null, foreign key(academy_id,student_id) references public.students(academy_id,id), plan_version_id uuid not null, foreign key(academy_id,plan_version_id) references public.plan_versions(academy_id,id), starts_on date not null, ends_on date not null, next_charge_on date not null, anchor_day int not null check(anchor_day between 1 and 31), billing_mode text not null default 'aniversario' check(billing_mode in ('aniversario','fijo')), status text not null default 'activa' check(status in ('activa','congelada','cancelada')), remaining_classes int check(remaining_classes>=0), discount numeric(14,2) not null default 0 check(discount>=0), frozen_until date, unique(student_id,plan_version_id,starts_on), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.membership_events (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), membership_id uuid not null, foreign key(academy_id,membership_id) references public.memberships(academy_id,id), action text not null, reason text not null, actor uuid not null, effective_on date not null, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.charges (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), student_id uuid , foreign key(academy_id,student_id) references public.students(academy_id,id), membership_id uuid , foreign key(academy_id,membership_id) references public.memberships(academy_id,id), description text not null, amount numeric(14,2) not null check(amount>=0), due_on date not null, period_on date, source text not null default 'manual', status text not null default 'emitido' check(status in ('emitido','anulado')), unique(membership_id,period_on), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.charge_adjustments (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), charge_id uuid not null, foreign key(academy_id,charge_id) references public.charges(academy_id,id), amount numeric(14,2) not null check(amount<>0), reason text not null, actor uuid not null, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.payment_methods (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), name text not null, kind text not null check(kind in ('efectivo','transferencia','tarjeta','otro')), requires_verification boolean not null default false, fee_percent numeric(7,4) not null default 0 check(fee_percent between 0 and 100), fee_fixed numeric(14,2) not null default 0 check(fee_fixed>=0), active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.accounts (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), name text not null, kind text not null check(kind in ('recepcion','chica','banco')), active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.cash_sessions (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), account_id uuid not null, foreign key(academy_id,account_id) references public.accounts(academy_id,id), cashier uuid not null, opened_at timestamptz not null default now(), closed_at timestamptz, opening_amount numeric(14,2) not null check(opening_amount>=0), expected numeric(14,2), counted numeric(14,2), difference numeric(14,2), reason text, approved_by uuid, created_at timestamptz not null default now(), unique(academy_id,id));
create unique index one_open_cash_session on public.cash_sessions(account_id) where closed_at is null;
create table public.payments (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), student_id uuid , foreign key(academy_id,student_id) references public.students(academy_id,id), payer_id uuid , foreign key(academy_id,payer_id) references public.contacts(academy_id,id), account_id uuid not null, foreign key(academy_id,account_id) references public.accounts(academy_id,id), method_id uuid not null, foreign key(academy_id,method_id) references public.payment_methods(academy_id,id), session_id uuid , foreign key(academy_id,session_id) references public.cash_sessions(academy_id,id), amount numeric(14,2) not null check(amount>0), tendered numeric(14,2) not null check(tendered>=amount), fee numeric(14,2) not null default 0 check(fee>=0), status text not null check(status in ('pendiente','confirmado')), reference text, receipt_number bigint not null, actor uuid not null, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.payment_applications (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), payment_id uuid not null, foreign key(academy_id,payment_id) references public.payments(academy_id,id), charge_id uuid not null, foreign key(academy_id,charge_id) references public.charges(academy_id,id), amount numeric(14,2) not null check(amount>0), confirmed boolean not null default false, unique(payment_id,charge_id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.account_movements (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), account_id uuid not null, foreign key(academy_id,account_id) references public.accounts(academy_id,id), session_id uuid , foreign key(academy_id,session_id) references public.cash_sessions(academy_id,id), amount numeric(14,2) not null check(amount<>0), kind text not null check(kind in ('cobro','egreso','transferencia','aporte','retiro','apertura','ajuste','reembolso','comision')), source_id uuid not null, description text not null, actor uuid not null, reconciled_on date, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.refunds (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), payment_id uuid not null, foreign key(academy_id,payment_id) references public.payments(academy_id,id), amount numeric(14,2) not null check(amount>0), reason text not null, actor uuid not null, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.refund_applications (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), refund_id uuid not null, foreign key(academy_id,refund_id) references public.refunds(academy_id,id), application_id uuid not null, foreign key(academy_id,application_id) references public.payment_applications(academy_id,id), amount numeric(14,2) not null check(amount>0), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.transfers (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), from_account_id uuid not null, foreign key(academy_id,from_account_id) references public.accounts(academy_id,id), to_account_id uuid not null, foreign key(academy_id,to_account_id) references public.accounts(academy_id,id), amount numeric(14,2) not null check(amount>0), reason text not null, check(from_account_id<>to_account_id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.commitments (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), student_id uuid not null, foreign key(academy_id,student_id) references public.students(academy_id,id), due_on date not null, amount numeric(14,2) not null check(amount>0), notes text not null, status text not null default 'pendiente' check(status in ('pendiente','cumplido','incumplido')), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.product_categories (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), name text not null, active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.products (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), category_id uuid , foreign key(academy_id,category_id) references public.product_categories(academy_id,id), name text not null, kind text not null default 'venta' check(kind in ('venta','consumible','equipo','servicio')), active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.product_variants (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), product_id uuid not null, foreign key(academy_id,product_id) references public.products(academy_id,id), name text not null, code text not null, size text, color text, unit text not null default 'unidad', price numeric(14,2) not null check(price>=0), min_stock numeric(14,3) not null default 0 check(min_stock>=0), active boolean not null default true, unique(academy_id,code), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.stock (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), variant_id uuid not null, foreign key(academy_id,variant_id) references public.product_variants(academy_id,id), quantity numeric(14,3) not null default 0 check(quantity>=0), average_cost numeric(14,4) not null default 0 check(average_cost>=0), unique(branch_id,variant_id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.inventory_movements (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), variant_id uuid not null, foreign key(academy_id,variant_id) references public.product_variants(academy_id,id), quantity numeric(14,3) not null check(quantity<>0), unit_cost numeric(14,4) not null check(unit_cost>=0), kind text not null, source_id uuid not null, reason text not null, actor uuid not null, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.suppliers (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), name text not null, email text, phone text, tax_id text, active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.expenses (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), supplier_id uuid , foreign key(academy_id,supplier_id) references public.suppliers(academy_id,id), description text not null, category text not null, amount numeric(14,2) not null check(amount>0), due_on date not null, incurred_on date not null, status text not null default 'pendiente' check(status in ('pendiente','aprobado','anulado')), approved_by uuid, source text not null default 'operativo', source_id uuid, document_path text, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.expense_payments (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), expense_id uuid not null, foreign key(academy_id,expense_id) references public.expenses(academy_id,id), account_id uuid not null, foreign key(academy_id,account_id) references public.accounts(academy_id,id), session_id uuid , foreign key(academy_id,session_id) references public.cash_sessions(academy_id,id), amount numeric(14,2) not null check(amount>0), actor uuid not null, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.expense_templates (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), description text not null, category text not null, amount numeric(14,2) not null check(amount>0), next_due_on date not null, months int not null default 1 check(months between 1 and 12), active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.purchases (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), supplier_id uuid not null, foreign key(academy_id,supplier_id) references public.suppliers(academy_id,id), expense_id uuid not null, foreign key(academy_id,expense_id) references public.expenses(academy_id,id), ordered_on date not null, status text not null default 'pedido' check(status in ('pedido','parcial','recibido','anulado')), reference text, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.purchase_lines (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), purchase_id uuid not null, foreign key(academy_id,purchase_id) references public.purchases(academy_id,id), variant_id uuid not null, foreign key(academy_id,variant_id) references public.product_variants(academy_id,id), quantity numeric(14,3) not null check(quantity>0), unit_cost numeric(14,4) not null check(unit_cost>=0), received numeric(14,3) not null default 0 check(received between 0 and quantity), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.stock_transfers (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), to_branch_id uuid not null, foreign key(academy_id,to_branch_id) references public.branches(academy_id,id), variant_id uuid not null, foreign key(academy_id,variant_id) references public.product_variants(academy_id,id), quantity numeric(14,3) not null check(quantity>0), unit_cost numeric(14,4) not null, status text not null default 'enviado' check(status in ('enviado','recibido')), reason text not null, check(branch_id<>to_branch_id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.equipment (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), variant_id uuid , foreign key(academy_id,variant_id) references public.product_variants(academy_id,id), name text not null, location text not null, status text not null default 'operativo' check(status in ('operativo','mantenimiento','baja')), maintenance_on date, notes text, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.sales (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), student_id uuid , foreign key(academy_id,student_id) references public.students(academy_id,id), customer_name text, charge_id uuid not null, foreign key(academy_id,charge_id) references public.charges(academy_id,id), total numeric(14,2) not null check(total>=0), discount numeric(14,2) not null default 0, seller uuid not null, status text not null default 'confirmada' check(status in ('confirmada','devuelta')), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.sale_lines (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), sale_id uuid not null, foreign key(academy_id,sale_id) references public.sales(academy_id,id), variant_id uuid not null, foreign key(academy_id,variant_id) references public.product_variants(academy_id,id), quantity numeric(14,3) not null check(quantity>0), unit_price numeric(14,2) not null check(unit_price>=0), unit_cost numeric(14,4) not null check(unit_cost>=0), discount numeric(14,2) not null default 0, returned numeric(14,3) not null default 0 check(returned between 0 and quantity), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.employees (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), name text not null, email text, phone text, position text not null, status text not null default 'activo' check(status in ('activo','inactivo')), linked_user_id uuid references auth.users(id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.compensation_versions (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), employee_id uuid not null, foreign key(academy_id,employee_id) references public.employees(academy_id,id), effective_on date not null, fixed_amount numeric(14,2) not null default 0 check(fixed_amount>=0), hourly_rate numeric(14,2) not null default 0 check(hourly_rate>=0), class_rate numeric(14,2) not null default 0 check(class_rate>=0), sale_percent numeric(7,4) not null default 0 check(sale_percent between 0 and 100), private_percent numeric(7,4) not null default 0 check(private_percent between 0 and 100), accrual text not null default 'cobro' check(accrual in ('cobro','venta')), unique(employee_id,effective_on), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.staff_activities (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), employee_id uuid not null, foreign key(academy_id,employee_id) references public.employees(academy_id,id), compensation_version_id uuid not null, foreign key(academy_id,compensation_version_id) references public.compensation_versions(academy_id,id), kind text not null check(kind in ('hora','clase','venta','privada','ajuste','anticipo')), units numeric(14,3) not null default 1, base_amount numeric(14,2) not null default 0, earned numeric(14,2) not null, activity_on date not null, source_id uuid, approved boolean not null default false, unique(employee_id,kind,source_id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.settlements (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), employee_id uuid not null, foreign key(academy_id,employee_id) references public.employees(academy_id,id), expense_id uuid not null, foreign key(academy_id,expense_id) references public.expenses(academy_id,id), from_on date not null, to_on date not null, total numeric(14,2) not null check(total>=0), status text not null default 'revision' check(status in ('revision','aprobada','pagada')), unique(employee_id,from_on,to_on), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.settlement_lines (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), settlement_id uuid not null, foreign key(academy_id,settlement_id) references public.settlements(academy_id,id), activity_id uuid not null, foreign key(academy_id,activity_id) references public.staff_activities(academy_id,id), amount numeric(14,2) not null, unique(activity_id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.class_templates (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), name text not null, discipline_id uuid not null, foreign key(academy_id,discipline_id) references public.disciplines(academy_id,id), room_id uuid not null, foreign key(academy_id,room_id) references public.rooms(academy_id,id), instructor_id uuid not null, foreign key(academy_id,instructor_id) references public.employees(academy_id,id), weekday int not null check(weekday between 0 and 6), starts_time time not null, duration_minutes int not null check(duration_minutes>0), capacity int not null check(capacity>0), level text, age_group text, active boolean not null default true, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.classes (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), name text not null, discipline_id uuid not null, foreign key(academy_id,discipline_id) references public.disciplines(academy_id,id), room_id uuid not null, foreign key(academy_id,room_id) references public.rooms(academy_id,id), instructor_id uuid not null, foreign key(academy_id,instructor_id) references public.employees(academy_id,id), substitute_id uuid , foreign key(academy_id,substitute_id) references public.employees(academy_id,id), template_id uuid , foreign key(academy_id,template_id) references public.class_templates(academy_id,id), starts_at timestamptz not null, ends_at timestamptz not null, capacity int not null check(capacity>0), kind text not null default 'regular' check(kind in ('regular','privada','prueba','evento','seminario')), status text not null default 'programada' check(status in ('programada','cancelada','impartida')), reason text, check(ends_at>starts_at), unique(template_id,starts_at), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.reservations (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), class_id uuid not null, foreign key(academy_id,class_id) references public.classes(academy_id,id), student_id uuid not null, foreign key(academy_id,student_id) references public.students(academy_id,id), status text not null check(status in ('reservada','espera','cancelada','ausente')), unique(class_id,student_id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.attendance (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), class_id uuid not null, foreign key(academy_id,class_id) references public.classes(academy_id,id), student_id uuid not null, foreign key(academy_id,student_id) references public.students(academy_id,id), membership_id uuid , foreign key(academy_id,membership_id) references public.memberships(academy_id,id), exception_reason text, actor uuid not null, unique(class_id,student_id), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.holidays (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid not null, foreign key(academy_id,branch_id) references public.branches(academy_id,id), day date not null, reason text not null, unique(branch_id,day), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.notifications (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid , foreign key(academy_id,branch_id) references public.branches(academy_id,id), kind text not null, title text not null, entity_id uuid, read_at timestamptz, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.audit_log (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), branch_id uuid , foreign key(academy_id,branch_id) references public.branches(academy_id,id), actor uuid, entity text not null, entity_id uuid, action text not null, reason text, details jsonb not null default '{}', created_at timestamptz not null default now(), unique(academy_id,id));
create table public.operation_keys (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), key uuid not null, action text not null, payload jsonb not null, result jsonb, unique(academy_id,key), created_at timestamptz not null default now(), unique(academy_id,id));
create table public.job_runs (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), started_at timestamptz not null default now(), finished_at timestamptz, generated int not null default 0, remaining boolean not null default false, error text, created_at timestamptz not null default now(), unique(academy_id,id));
create table public.document_counters (id uuid primary key default gen_random_uuid(), academy_id uuid not null references public.academies(id), kind text not null, next_number bigint not null default 1, unique(academy_id,kind), created_at timestamptz not null default now(), unique(academy_id,id));

create function private.has_permission(a uuid, b uuid, p text) returns boolean
language sql stable security definer set search_path = '' as $$
 select auth.uid() is not null and exists (
 select 1 from public.internal_members m join public.member_roles mr on mr.member_id=m.id and mr.academy_id=m.academy_id
 join public.roles r on r.id=mr.role_id and r.academy_id=m.academy_id
 where m.user_id=auth.uid() and m.academy_id=a and m.active and r.active
 and (b is null or m.all_branches or b=any(m.branch_ids))
 and (p=any(r.permissions) or '*'=any(r.permissions)))
$$;
revoke all on function private.has_permission(uuid,uuid,text) from public;
grant execute on function private.has_permission(uuid,uuid,text) to authenticated;
create function private.immutable_academy() returns trigger language plpgsql set search_path='' as $$
begin if new.academy_id <> old.academy_id then raise exception 'No se puede cambiar la academia'; end if; return new; end $$;
create function private.audit_master() returns trigger language plpgsql security definer set search_path='' as $$
begin
 insert into public.audit_log(academy_id,actor,entity,entity_id,action) values(new.academy_id,auth.uid(),tg_table_name,new.id,tg_op);
 return new;
end $$;
alter table public.academies enable row level security;
grant select on public.academies to authenticated;
create policy academy_read on public.academies for select to authenticated using(private.has_permission(id,null,'dashboard.read'));
alter table public.branches enable row level security;
grant select on public.branches to authenticated;
create policy branches_read on public.branches for select to authenticated using (private.has_permission(academy_id,id,'settings.read'));
create trigger immutable_academy before update on public.branches for each row execute function private.immutable_academy();
create index branches_academy_idx on public.branches(academy_id);
grant insert,update on public.branches to authenticated;
create policy branches_insert on public.branches for insert to authenticated with check(private.has_permission(academy_id,id,'settings.write'));
create policy branches_update on public.branches for update to authenticated using(private.has_permission(academy_id,id,'settings.write')) with check(private.has_permission(academy_id,id,'settings.write'));
create trigger audit_master after insert or update on public.branches for each row execute function private.audit_master();
