create view public.charge_balances with(security_invoker=true) as
 select c.*, c.amount+coalesce((select sum(ca.amount) from public.charge_adjustments ca where ca.charge_id=c.id),0)-coalesce((select sum(pa.amount) from public.payment_applications pa where pa.charge_id=c.id and pa.confirmed),0)
 +coalesce((select sum(ra.amount) from public.refund_applications ra join public.payment_applications pa on pa.id=ra.application_id where pa.charge_id=c.id),0) as balance
 from public.charges c where c.status='emitido';
grant select on public.charge_balances to authenticated;
create view public.account_balances with(security_invoker=true) as select a.*, coalesce((select sum(m.amount) from public.account_movements m where m.account_id=a.id),0) as balance from public.accounts a;
grant select on public.account_balances to authenticated;
create view public.expense_balances with(security_invoker=true) as select e.*,e.amount-coalesce((select sum(p.amount) from public.expense_payments p where p.expense_id=e.id),0) as balance from public.expenses e where status<>'anulado';
grant select on public.expense_balances to authenticated;
